display.text:
import { useState, useEffect, useCallback } from 'react';
// @ts-ignore - Importing from local workspace without type definitions might cause TS issues
import { KnirvWallet as KnirvVault } from 'knirvwallet-module/wallet';
// @ts-ignore
import { Account } from 'knirvwallet-module/wallet/account';
import { DVEVault } from '@/shared/types';
import { getVaultSession, updateVaultSession, type VaultStatus } from './vaultSession';

const VAULT_STORAGE_KEY = 'knirv_vault';
const DVE_DERIVATION_BASE_PATH = "m/44'/60'/1'/0/";

export const useVault = () => {
  const vaultSession = getVaultSession();
  const [vault, setVault] = useState<any | null>(() => vaultSession.vault);
  const [status, setStatus] = useState<VaultStatus>(() => (
    vaultSession.status === 'initializing'
      ? (localStorage.getItem(VAULT_STORAGE_KEY) ? 'locked' : 'no_vault')
      : vaultSession.status
  ));
  const [accounts, setAccounts] = useState<Account[]>(() => vaultSession.accounts);
  const [currentAccount, setCurrentAccount] = useState<Account | null>(() => vaultSession.currentAccount);
  const [dveVaults, setDVEVaults] = useState<DVEVault[]>(() => vaultSession.dveVaults);
  const [error, setError] = useState<string | null>(() => vaultSession.error);

  // Initialize vault state from storage
  useEffect(() => {
    const checkStorage = () => {
      const currentSession = getVaultSession();
      if (currentSession.status !== 'initializing') {
        setVault(currentSession.vault);
        setStatus(currentSession.status);
        setAccounts(currentSession.accounts);
        setCurrentAccount(currentSession.currentAccount);
        setDVEVaults(currentSession.dveVaults);
        setError(currentSession.error);
        return;
      }

      const storedVault = localStorage.getItem(VAULT_STORAGE_KEY);
      if (storedVault) {
        setStatus('locked');
      } else {
        setStatus('no_vault');
      }
    };
    checkStorage();
  }, []);

  // Update accounts when vault changes
  useEffect(() => {
    if (vault) {
      setAccounts(vault.accounts || []);
      setCurrentAccount(vault.currentAccount || null);
    }
  }, [vault]);

  const createVault = useCallback(async (password: string): Promise<string> => {
    try {
      setStatus('initializing');
      const mnemonic = KnirvVault.generateMnemonic(12);
      const newVault = await KnirvVault.createByMnemonic(mnemonic);
      const serialized = await newVault.serialize(password);
      localStorage.setItem(VAULT_STORAGE_KEY, serialized);
      setVault(newVault);
      updateVaultSession({
        vault: newVault,
        status: 'unlocked',
        accounts: newVault.accounts || [],
        currentAccount: newVault.currentAccount || null,
        dveVaults: [],
        error: null,
      });
      setStatus('unlocked');
      return mnemonic;
    } catch (err: any) {
      console.error('Failed to create vault:', err);
      setError(err.message || 'Failed to create vault');
      updateVaultSession({ error: err.message || 'Failed to create vault' });
      setStatus('no_vault');
      throw err;
    }
  }, []);

  const importVault = useCallback(async (mnemonic: string, password: string) => {
    try {
      setStatus('initializing');
      const newVault = await KnirvVault.createByMnemonic(mnemonic);
      const serialized = await newVault.serialize(password);
      localStorage.setItem(VAULT_STORAGE_KEY, serialized);
      setVault(newVault);
      updateVaultSession({
        vault: newVault,
        status: 'unlocked',
        accounts: newVault.accounts || [],
        currentAccount: newVault.currentAccount || null,
        dveVaults: [],
        error: null,
      });
      setStatus('unlocked');
    } catch (err: any) {
      console.error('Failed to import vault:', err);
      setError(err.message || 'Failed to import vault');
      updateVaultSession({ error: err.message || 'Failed to import vault' });
      setStatus('no_vault');
      throw err;
    }
  }, []);

  const unlockVault = useCallback(async (password: string) => {
    try {
      setStatus('initializing');
      const storedVault = localStorage.getItem(VAULT_STORAGE_KEY);
      if (!storedVault) {
        throw new Error('No vault found');
      }
      const unlockedVault = await KnirvVault.deserialize(storedVault, password);
      setVault(unlockedVault);
      updateVaultSession({
        vault: unlockedVault,
        status: 'unlocked',
        accounts: unlockedVault.accounts || [],
        currentAccount: unlockedVault.currentAccount || null,
        dveVaults: [],
        error: null,
      });
      setStatus('unlocked');
      setError(null);
    } catch (err: any) {
      console.error('Failed to unlock vault:', err);
      setError('Incorrect password');
      updateVaultSession({ error: 'Incorrect password' });
      setStatus('locked');
      throw err;
    }
  }, []);

  const lockVault = useCallback(() => {
    setVault(null);
    setAccounts([]);
    setCurrentAccount(null);
    setDVEVaults([]);
    setStatus('locked');
    updateVaultSession({
      vault: null,
      status: 'locked',
      accounts: [],
      currentAccount: null,
      dveVaults: [],
    });
  }, []);

  const clearVault = useCallback(() => {
    localStorage.removeItem(VAULT_STORAGE_KEY);
    setVault(null);
    setAccounts([]);
    setCurrentAccount(null);
    setDVEVaults([]);
    setStatus('no_vault');
    updateVaultSession({
      vault: null,
      status: 'no_vault',
      accounts: [],
      currentAccount: null,
      dveVaults: [],
      error: null,
    });
  }, []);

  const deriveDVEVault = useCallback(async (dveID: string, dveName: string, teeType: DVEVault['teeType'], index: number): Promise<DVEVault> => {
    if (!vault || status !== 'unlocked') {
      throw new Error('Vault is locked or not initialized');
    }
    const derivationPath = `${DVE_DERIVATION_BASE_PATH}${index}`;
    const dveVault: DVEVault = {
      dveID,
      dveName,
      vaultAddress: `${derivationPath}_${dveID.substring(0, 8)}`,
      derivationIndex: index,
      teeType,
      status: 'offline',
      stakeAmount: 0,
      reputationScore: 0,
      capabilities: [],
      attachedPolicies: [],
      badgeNFTIDs: [],
      supervisorAgentID: '',
      dveURI: `knirv://dve/${dveID}/${teeType}`,
    };
    setDVEVaults(prev => [...prev, dveVault]);
    return dveVault;
  }, [vault, status]);

  const updateDVEVaultStatus = useCallback((dveID: string, updates: Partial<DVEVault>) => {
    setDVEVaults(prev => {
      const next = prev.map(w => w.dveID === dveID ? { ...w, ...updates } : w);
      updateVaultSession({ dveVaults: next });
      return next;
    });
  }, []);

  const removeDVEVault = useCallback((dveID: string) => {
    setDVEVaults(prev => {
      const next = prev.filter(w => w.dveID !== dveID);
      updateVaultSession({ dveVaults: next });
      return next;
    });
  }, []);

  const signTransaction = useCallback(async (tx: any) => {
    if (!vault || status !== 'unlocked') {
      throw new Error('Vault is locked or not initialized');
    }
    return vault.signTransaction(tx);
  }, [vault, status]);

  return {
    vault,
    status,
    accounts,
    currentAccount,
    dveVaults,
    error,
    createVault,
    importVault,
    unlockVault,
    lockVault,
    clearVault,
    deriveDVEVault,
    updateDVEVaultStatus,
    removeDVEVault,
    signTransaction,
  };
};

